// Digital twin for Sense.MIC — analog MEMS microphone + amplifier + ADC.
//
// Signal chain (schematic truth): a Same Sky/CUI CMM-2718AT analog MEMS mic
// (−42 dBV/Pa, 57 dBA SNR, 130 dB AOP) is AC-coupled into an AD8605 op-amp with
// ~48× non-inverting gain (R4 47k / R3 1k), biased to mid-rail; the amplified
// output drives a MAX11645 12-bit I2C ADC (AIN0) AND is tapped out to a pad. The
// twin drives the world with a sound-level slider (dB SPL) and runs it through
// SPL → mic Vrms → ×48 gain → DC-biased 12-bit quantisation.
//
// PAD NOTE: the schematic routes the amplified analog output to pad 8. The
// canonical tile JSON is mid-reconciliation and currently labels pad 6 as the
// analog out (and still lists the old PUI AMM-2742 mic, no AD8605). This twin
// emits the analog out under the "AOUT" net so it follows wherever the JSON maps
// it; the DB still needs the mic part, the AD8605, and AOUT→pad 8 corrected.
import type { TileSim } from '../tileSim';

const I2C_ADDR = 0x36; // MAX11645 fixed I2C address
const AMP_GAIN = 48; // AD8605 non-inverting gain (1 + 47k/1k)
const MIC_MV_PER_PA = 7.943; // −42 dBV/Pa at the mic output
const ADC_FULL = 4096; // 12-bit

interface State {
  sound_level: number; // ambient SPL in dB the user drives
  vref_mv: number; // ADC reference (3300 VDD, 2048 internal)
  ref_sel: number; // sense_mic_ref_t code
  channel: number; // AIN0/AIN1
  scan: number; // scan mode code
  clock_sel: number; // internal/external clock
  polarity: number; // 0 unipolar, 1 bipolar
  asleep: number;

  [field: string]: number;
}

const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

// DC bias sits at mid-rail (the R1/R2 330k/330k divider biases the AD8605 input).
const dcOffset = () => Math.round(ADC_FULL / 2);

// SPL → pressure (Pa), 1 Pa = 94 dB SPL.
const pascals = (spl: number) => Math.pow(10, (spl - 94) / 20);
// Amplified RMS voltage at the ADC input (mV), before clipping to the rail.
function adcVrmsMv(s: State): number {
  return MIC_MV_PER_PA * pascals(s.asleep ? 0 : s.sound_level) * AMP_GAIN;
}
// RMS in ADC counts, clipped so the amp can't swing past the rail.
function rmsCounts(s: State): number {
  const mv = Math.min(adcVrmsMv(s), s.vref_mv / 2);
  return Math.round((mv / s.vref_mv) * ADC_FULL);
}
// An instantaneous sample = bias + a representative positive excursion.
const rawSample = (s: State) => clamp(dcOffset() + rmsCounts(s), 0, ADC_FULL - 1);
const toMv = (s: State, counts: number) => Math.round((counts * s.vref_mv) / ADC_FULL);

const sim: TileSim<State> = {
  tile: 'Sense.MIC',

  defaultState: {
    sound_level: 50, // quiet room
    vref_mv: 3300, // VDD reference (default)
    ref_sel: 0x00, // SENSE_MIC_REF_VDD
    channel: 0,
    scan: 0,
    clock_sel: 0,
    polarity: 0,
    asleep: 0,
  },

  controls: [
    {
      type: 'slider',
      field: 'sound_level',
      label: 'Sound level',
      min: 30,
      max: 120,
      step: 1,
      unit: 'dB SPL',
    },
    { type: 'toggle', field: 'asleep', label: 'Asleep' },
  ],

  hostCalls: {
    // ── lifecycle ──
    tile_sense_mic_find: () => ({ scalar: I2C_ADDR }),
    tile_sense_mic_init: () => ({ scalar: 0, nextState: { asleep: 0 } }),
    tile_sense_mic_sleep: () => ({ nextState: { asleep: 1 } }),
    tile_sense_mic_wake: () => ({ nextState: { asleep: 0 } }),
    tile_sense_mic_reset: () => ({ nextState: { asleep: 0 } }),

    // ── config ──
    tile_sense_mic_set_reference: ({ args }) => {
      const ref = pick(args, 0, 0);
      // VDD (0/1) → 3300 mV; internal/buffered (2/3) → 2048 mV.
      const vref = ref === 0x02 || ref === 0x03 ? 2048 : 3300;
      return { nextState: { ref_sel: ref, vref_mv: vref } };
    },
    tile_sense_mic_set_channel: ({ args }) => ({ nextState: { channel: pick(args, 0, 0) } }),
    tile_sense_mic_set_scan_mode: ({ args }) => ({ nextState: { scan: pick(args, 0, 0) } }),
    tile_sense_mic_set_clock_mode: ({ args }) => ({ nextState: { clock_sel: pick(args, 0, 0) } }),
    tile_sense_mic_set_polarity: ({ args }) => ({
      nextState: { polarity: pick(args, 0, 0) ? 1 : 0 },
    }),
    tile_sense_mic_get_vref_mv: ({ state }) => ({ scalar: state.vref_mv }),

    // ── data ──
    tile_sense_mic_get_raw: ({ state }) => ({ scalar: rawSample(state) }),
    tile_sense_mic_get_raw_mv: ({ state }) => ({ scalar: toMv(state, rawSample(state)) }),
    tile_sense_mic_get_audio_sample: ({ state }) => ({ scalar: rmsCounts(state) }),
    tile_sense_mic_get_dc_offset: () => ({ scalar: dcOffset() }),
    tile_sense_mic_calibrate: () => ({ scalar: dcOffset() }),
    tile_sense_mic_get_samples: ({ state }) => {
      // A few modeled samples around the bias point (one cycle's worth).
      const dc = dcOffset();
      const a = rmsCounts(state);
      return { array: [dc + a, dc, dc - a, dc, dc + a, dc, dc - a, dc] };
    },

    // ── pure-compute helpers (modeled from the level) ──
    tile_sense_mic_dc_level: () => ({ scalar: dcOffset() }),
    tile_sense_mic_peak_to_peak: ({ state }) => ({
      scalar: clamp(Math.round(2 * Math.SQRT2 * rmsCounts(state)), 0, ADC_FULL - 1),
    }),
    tile_sense_mic_rms: ({ state }) => ({ scalar: rmsCounts(state) }),
    tile_sense_mic_amplitude_mv: ({ state }) => ({
      scalar: Math.min(Math.round(adcVrmsMv(state)), state.vref_mv / 2),
    }),

    // ── tier-2 SPL / events (0.1 dB units) ──
    tile_sense_mic_read_spl_db: ({ state }) => ({
      scalar: state.asleep ? 300 : Math.round(state.sound_level * 10),
    }),
    tile_sense_mic_is_loud: ({ state, args }) => ({
      scalar: !state.asleep && state.sound_level * 10 > pick(args, 0, 700) ? 1 : 0,
    }),
    tile_sense_mic_wait_for_sound: ({ state, args }) => ({
      scalar: !state.asleep && state.sound_level * 10 > pick(args, 0, 700) ? 1 : 0,
    }),
    tile_sense_mic_detect_clap: ({ state }) => ({
      scalar: !state.asleep && state.sound_level > 85 ? 1 : 0,
    }),
  },

  provenance: {
    tile_sense_mic_find: 'canonical', // MAX11645 I2C 0x36
    tile_sense_mic_get_vref_mv: 'canonical', // 3300 VDD / 2048 internal
    tile_sense_mic_set_reference: 'canonical', // SETUP byte ref bits
    tile_sense_mic_get_raw: 'canonical', // 12-bit ADC sample
    tile_sense_mic_get_raw_mv: 'canonical', // raw·vref/4096
    tile_sense_mic_get_dc_offset: 'canonical',
    tile_sense_mic_dc_level: 'canonical',
    // inferred — modeled from the driven sound level + the 48× analog chain
    tile_sense_mic_get_audio_sample: 'inferred',
    tile_sense_mic_get_samples: 'inferred',
    tile_sense_mic_peak_to_peak: 'inferred',
    tile_sense_mic_rms: 'inferred',
    tile_sense_mic_amplitude_mv: 'inferred',
    tile_sense_mic_read_spl_db: 'inferred', // gain-corrected mic-sensitivity model
    tile_sense_mic_is_loud: 'inferred',
    tile_sense_mic_wait_for_sound: 'inferred',
    tile_sense_mic_detect_clap: 'inferred',
    tile_sense_mic_calibrate: 'inferred',
    power: 'inferred', // datasheet typicals; AD8605 + mic + ADC summed estimate
  },

  // Pad 8 (per schematic): the amplified analog output (mic ×48, DC-biased),
  // tapped alongside the ADC's AIN0. Emitted as a millivolt level under "AOUT"
  // so it tracks whatever pad the JSON maps that net to (pad 6 today, pad 8 once
  // the DB is reconciled). I2C is the bus on pads 4/5.
  padOutputs(state) {
    return { AOUT: toMv(state, rawSample(state)) };
  },

  // Electrical: a pure load on V+ (pad 10) / GND (pad 1). The AD8605 (~1 mA) and
  // mic (~250 µA) run continuously; the MAX11645 adds ~750 µA active and drops to
  // ~0.5 µA in shutdown — so sleep only trims the ADC, the analog front-end stays
  // on. Figures are datasheet typicals (estimate), hence power = inferred.
  power(state) {
    const adc = state.asleep ? 1 : 750; // µA
    const ua = 250 /* mic */ + 1000 /* AD8605 */ + adc;
    return {
      draw_ua: ua,
      rails: [
        {
          name: 'V+',
          role: 'supply',
          v_mv: 3300,
          i_ua: ua,
          pads: ['10'],
          note: state.asleep ? 'ADC shutdown; mic+amp still on' : 'mic + AD8605 + ADC active',
        },
      ],
    };
  },
};

export default sim;
